from lib import *
LES = [
L("lin", "B", "Linear inside: f(ax+b)", "ฟังก์ชันเชิงเส้นข้างใน: f(ax+b)",
 [T("<b>Theorem.</b> Let $F'=f$ on an interval $J$, and let $a\\neq0$, $b$ be real. Then on the interval $\\{x: ax+b\\in J\\}$, $$\\int f(ax+b)\\,dx=\\frac{1}{a}F(ax+b)+C.$$",
    "<b>ทฤษฎีบท</b> ให้ $F'=f$ บนช่วง $J$ และ $a\\neq0$, $b$ เป็นจำนวนจริง แล้วบนช่วง $\\{x: ax+b\\in J\\}$ $$\\int f(ax+b)\\,dx=\\frac{1}{a}F(ax+b)+C$$"),
  T("Examples of $F$: $\\int(ax+b)^{n}dx=\\dfrac{(ax+b)^{n+1}}{a(n+1)}$, $\\int e^{ax+b}dx=\\dfrac{e^{ax+b}}{a}$, $\\int\\cos(ax+b)\\,dx=\\dfrac{\\sin(ax+b)}{a}$, $\\int\\dfrac{dx}{ax+b}=\\dfrac{\\ln|ax+b|}{a}$.",
    "ตัวอย่าง: $\\int(ax+b)^{n}dx=\\dfrac{(ax+b)^{n+1}}{a(n+1)}$, $\\int e^{ax+b}dx=\\dfrac{e^{ax+b}}{a}$, $\\int\\cos(ax+b)\\,dx=\\dfrac{\\sin(ax+b)}{a}$, $\\int\\dfrac{dx}{ax+b}=\\dfrac{\\ln|ax+b|}{a}$")],
 [S("The map $x\\mapsto ax+b$ is continuous and $a\\neq0$, so $\\{x:ax+b\\in J\\}$ is an interval. On it the chain rule gives", "ฟังก์ชัน $x\\mapsto ax+b$ ต่อเนื่องและ $a\\neq0$ ดังนั้น $\\{x:ax+b\\in J\\}$ เป็นช่วง บนช่วงนี้กฎลูกโซ่ให้", "\\frac{d}{dx}\\left[\\frac1aF(ax+b)\\right]=\\frac1a\\cdot F'(ax+b)\\cdot a=f(ax+b)."),
  S("So $\\frac1aF(ax+b)$ is an antiderivative, and by the lemma of lesson 1 every antiderivative is this plus a constant. $\\blacksquare$", "ดังนั้น $\\frac1aF(ax+b)$ เป็นปฏิยานุพันธ์ และจากบทตั้งในบทที่ 1 ทุกตัวต่างจากนี้เพียงค่าคงตัว $\\blacksquare$")],
 [X(r"\int(2x+1)^{5}\,dx", "(2x+1)^6/12", r"\frac{(2x+1)^{6}}{12}+C", "(2*x+1)**5", ("i", "0", "1"), [r"a=2,\ F(u)=\frac{u^{6}}{6}", r"\frac12\cdot\frac{(2x+1)^{6}}{6}+C=\frac{(2x+1)^{6}}{12}+C"]),
  X(r"\int_{0}^{\frac{\pi}{4}}\cos2x\,dx", "1/2", r"\frac12", "cos(2*x)", ("d", "0", "pi/4"), [r"\left[\tfrac12\sin2x\right]_{0}^{\frac{\pi}{4}}=\tfrac12\cdot1-0=\frac12"])],
 [P(r"\int_{0}^{1}(3x+1)^{3}\,dx", "85/4", r"\frac{85}{4}", "(3*x+1)**3", ("d", "0", "1"), [r"\left[\frac{(3x+1)^{4}}{12}\right]_{0}^{1}=\frac{256-1}{12}=\frac{85}{4}"], "Divide by $a=3$ as well as by the new power.", "หารด้วย $a=3$ และเลขชี้กำลังใหม่"),
  P(r"\int_{0}^{1}e^{2x+1}\,dx", "(e^3-e)/2", r"\frac{e^{3}-e}{2}", "exp(2*x+1)", ("d", "0", "1"), [r"\left[\tfrac12e^{2x+1}\right]_{0}^{1}=\frac{e^{3}-e}{2}"], "$\\int e^{ax+b}dx=\\frac{1}{a}e^{ax+b}$.", "$\\int e^{ax+b}dx=\\frac{1}{a}e^{ax+b}$"),
  P(r"\int_{0}^{\frac{\pi}{6}}\sin3x\,dx", "1/3", r"\frac13", "sin(3*x)", ("d", "0", "pi/6"), [r"\left[-\tfrac13\cos3x\right]_{0}^{\frac{\pi}{6}}=0+\frac13=\frac13"], "$\\cos\\frac{\\pi}{2}=0$.", "$\\cos\\frac{\\pi}{2}=0$"),
  P(r"\int_{1}^{3}\frac{1}{2x-1}\,dx", "ln(5)/2", r"\frac{\ln5}{2}", "1/(2*x-1)", ("d", "1", "3"), [r"\left[\tfrac12\ln|2x-1|\right]_{1}^{3}=\tfrac12(\ln5-\ln1)=\frac{\ln5}{2}"], "$\\int\\frac{dx}{ax+b}=\\frac{1}{a}\\ln|ax+b|$.", "$\\int\\frac{dx}{ax+b}=\\frac{1}{a}\\ln|ax+b|$"),
  P(r"\int\sec^{2}4x\,dx", "tan(4x)/4", r"\frac{\tan4x}{4}+C", "sec(4*x)**2", ("i", "0", "0.3"), [r"\frac14\tan4x+C"], "$\\int\\sec^{2}u\\,du=\\tan u$.", "$\\int\\sec^{2}u\\,du=\\tan u$")]),

L("flog", "B", "The f′/f rule", "กฎ f′/f",
 [T("<b>Theorem.</b> Let $f$ be differentiable on an interval $I$ with $f'$ continuous and $f(x)\\neq0$ for all $x\\in I$. Then $$\\int\\frac{f'(x)}{f(x)}\\,dx=\\ln|f(x)|+C\\quad\\text{on }I.$$",
    "<b>ทฤษฎีบท</b> ให้ $f$ หาอนุพันธ์ได้บนช่วง $I$ โดย $f'$ ต่อเนื่องและ $f(x)\\neq0$ ทุก $x\\in I$ แล้ว $$\\int\\frac{f'(x)}{f(x)}\\,dx=\\ln|f(x)|+C\\quad\\text{บน }I$$"),
  T("Spot it: the top is (a multiple of) the derivative of the bottom.", "วิธีสังเกต: ตัวเศษเป็น (พหุคูณของ) อนุพันธ์ของตัวส่วน")],
 [S("$f$ is continuous and never $0$ on the interval $I$, so by the intermediate value theorem it cannot change sign: either $f>0$ on all of $I$ or $f<0$ on all of $I$.", "$f$ ต่อเนื่องและไม่เป็น $0$ บนช่วง $I$ จากทฤษฎีบทค่าระหว่างกลางจึงเปลี่ยนเครื่องหมายไม่ได้: $f>0$ ทั้งช่วง หรือ $f<0$ ทั้งช่วง"),
  S("If $f>0$: by the chain rule", "ถ้า $f>0$: จากกฎลูกโซ่", "\\frac{d}{dx}\\ln f(x)=\\frac{f'(x)}{f(x)}."),
  S("If $f<0$: $\\ln|f|=\\ln(-f)$ and", "ถ้า $f<0$: $\\ln|f|=\\ln(-f)$ และ", "\\frac{d}{dx}\\ln(-f(x))=\\frac{-f'(x)}{-f(x)}=\\frac{f'(x)}{f(x)}."),
  S("In both cases $\\ln|f|$ is an antiderivative; by the lemma of lesson 1 all others differ by a constant. $\\blacksquare$", "ทั้งสองกรณี $\\ln|f|$ เป็นปฏิยานุพันธ์ และจากบทตั้งในบทที่ 1 ตัวอื่นต่างกันเพียงค่าคงตัว $\\blacksquare$")],
 [X(r"\int\frac{2x}{x^{2}+1}\,dx", "ln(x^2+1)", r"\ln\left(x^{2}+1\right)+C", "2*x/(x**2+1)", ("i", "0", "2"), [r"f=x^{2}+1,\ f'=2x", r"\ln\left(x^{2}+1\right)+C\quad(f>0)"]),
  X(r"\int_{\frac{\pi}{6}}^{\frac{\pi}{2}}\cot x\,dx", "ln(2)", r"\ln2", "cot(x)", ("d", "pi/6", "pi/2"), [r"\cot x=\frac{\cos x}{\sin x}=\frac{f'}{f},\ f=\sin x", r"\left[\ln\sin x\right]_{\frac{\pi}{6}}^{\frac{\pi}{2}}=\ln1-\ln\tfrac12=\ln2"])],
 [P(r"\int_{0}^{1}\frac{3x^{2}}{x^{3}+1}\,dx", "ln(2)", r"\ln2", "3*x**2/(x**3+1)", ("d", "0", "1"), [r"\left[\ln\left(x^{3}+1\right)\right]_{0}^{1}=\ln2"], "The top is the derivative of the bottom.", "ตัวเศษเป็นอนุพันธ์ของตัวส่วน"),
  P(r"\int_{0}^{\frac{\pi}{3}}\frac{\sin x}{2-\cos x}\,dx", "ln(3/2)", r"\ln\frac32", "sin(x)/(2-cos(x))", ("d", "0", "pi/3"), [r"f=2-\cos x,\ f'=\sin x", r"\left[\ln(2-\cos x)\right]_{0}^{\frac{\pi}{3}}=\ln\tfrac32-\ln1"], "Differentiate $2-\\cos x$.", "หาอนุพันธ์ของ $2-\\cos x$"),
  P(r"\int_{1}^{2}\frac{2x+1}{x^{2}+x}\,dx", "ln(3)", r"\ln3", "(2*x+1)/(x**2+x)", ("d", "1", "2"), [r"\left[\ln\left(x^{2}+x\right)\right]_{1}^{2}=\ln6-\ln2=\ln3"], "$(x^{2}+x)'=2x+1$.", "$(x^{2}+x)'=2x+1$"),
  P(r"\int_{0}^{1}\frac{x}{x^{2}+3}\,dx", "ln(4/3)/2", r"\frac12\ln\frac43", "x/(x**2+3)", ("d", "0", "1"), [r"\frac{x}{x^{2}+3}=\frac12\cdot\frac{2x}{x^{2}+3}", r"\left[\tfrac12\ln\left(x^{2}+3\right)\right]_{0}^{1}=\tfrac12\ln\tfrac43"], "Make the top exactly $2x$ by multiplying and dividing by $2$.", "ทำตัวเศษให้เป็น $2x$ โดยคูณและหารด้วย $2$"),
  P(r"\int\frac{e^{x}}{e^{x}+5}\,dx", "ln(e^x+5)", r"\ln\left(e^{x}+5\right)+C", "exp(x)/(exp(x)+5)", ("i", "0", "2"), [r"\ln\left(e^{x}+5\right)+C"], "$(e^{x}+5)'=e^{x}$.", "$(e^{x}+5)'=e^{x}$")]),

L("fpow", "B", "Reverse chain rule: f′fⁿ and f′e^f", "กฎลูกโซ่ย้อนกลับ: f′fⁿ และ f′e^f",
 [T("<b>Theorem.</b> Let $g$ be continuously differentiable on an interval $I$. Then $$\\int g'(x)\\,e^{g(x)}\\,dx=e^{g(x)}+C,$$ and for real $n\\neq-1$ (with $g>0$ on $I$ if $n$ is not an integer) $$\\int g'(x)\\,\\big[g(x)\\big]^{n}\\,dx=\\frac{\\big[g(x)\\big]^{n+1}}{n+1}+C.$$",
    "<b>ทฤษฎีบท</b> ให้ $g$ หาอนุพันธ์ได้ต่อเนื่องบนช่วง $I$ แล้ว $$\\int g'(x)\\,e^{g(x)}\\,dx=e^{g(x)}+C$$ และสำหรับจำนวนจริง $n\\neq-1$ (โดย $g>0$ บน $I$ ถ้า $n$ ไม่ใช่จำนวนเต็ม) $$\\int g'(x)\\,\\big[g(x)\\big]^{n}\\,dx=\\frac{\\big[g(x)\\big]^{n+1}}{n+1}+C$$")],
 [S("By the chain rule, on $I$:", "จากกฎลูกโซ่ บน $I$:", "\\frac{d}{dx}e^{g(x)}=e^{g(x)}g'(x),\\qquad \\frac{d}{dx}\\frac{[g(x)]^{n+1}}{n+1}=\\frac{(n+1)[g(x)]^{n}g'(x)}{n+1}=g'(x)[g(x)]^{n}."),
  S("The condition $g>0$ makes $[g(x)]^{n}$ defined and differentiable for non-integer $n$. By the lemma of lesson 1 these are all the antiderivatives. $\\blacksquare$", "เงื่อนไข $g>0$ ทำให้ $[g(x)]^{n}$ นิยามและหาอนุพันธ์ได้เมื่อ $n$ ไม่ใช่จำนวนเต็ม และจากบทตั้งในบทที่ 1 นี่คือปฏิยานุพันธ์ทั้งหมด $\\blacksquare$")],
 [X(r"\int x\left(x^{2}+1\right)^{4}dx", "(x^2+1)^5/10", r"\frac{\left(x^{2}+1\right)^{5}}{10}+C", "x*(x**2+1)**4", ("i", "0", "1"), [r"g=x^{2}+1,\ g'=2x:\ x=\tfrac12g'", r"\tfrac12\cdot\frac{g^{5}}{5}=\frac{\left(x^{2}+1\right)^{5}}{10}+C"]),
  X(r"\int2xe^{x^{2}}\,dx", "e^(x^2)", r"e^{x^{2}}+C", "2*x*exp(x**2)", ("i", "0", "1"), [r"g=x^{2},\ g'=2x", r"e^{x^{2}}+C"])],
 [P(r"\int_{0}^{1}x\left(x^{2}+1\right)^{3}dx", "15/8", r"\frac{15}{8}", "x*(x**2+1)**3", ("d", "0", "1"), [r"\left[\frac{\left(x^{2}+1\right)^{4}}{8}\right]_{0}^{1}=\frac{16-1}{8}=\frac{15}{8}"], "$g=x^{2}+1$, so $x=\\tfrac12g'$.", "$g=x^{2}+1$ ดังนั้น $x=\\tfrac12g'$"),
  P(r"\int_{0}^{\frac{\pi}{2}}\cos x\sin^{3}x\,dx", "1/4", r"\frac14", "cos(x)*sin(x)**3", ("d", "0", "pi/2"), [r"g=\sin x:\ \left[\tfrac14\sin^{4}x\right]_{0}^{\frac{\pi}{2}}=\frac14"], "$g=\\sin x$, $g'=\\cos x$.", "$g=\\sin x$, $g'=\\cos x$"),
  P(r"\int_{0}^{1}xe^{x^{2}}\,dx", "(e-1)/2", r"\frac{e-1}{2}", "x*exp(x**2)", ("d", "0", "1"), [r"\left[\tfrac12e^{x^{2}}\right]_{0}^{1}=\frac{e-1}{2}"], "$g=x^{2}$; you need a factor $\\tfrac12$.", "$g=x^{2}$ ต้องมีตัวคูณ $\\tfrac12$"),
  P(r"\int_{0}^{\frac{\pi}{2}}\sin x\,e^{\cos x}\,dx", "e-1", r"e-1", "sin(x)*exp(cos(x))", ("d", "0", "pi/2"), [r"g=\cos x,\ g'=-\sin x", r"\left[-e^{\cos x}\right]_{0}^{\frac{\pi}{2}}=-1+e"], "$g=\\cos x$ and watch the minus sign.", "$g=\\cos x$ และระวังเครื่องหมายลบ"),
  P(r"\int_{0}^{1}x^{2}\sqrt{x^{3}+1}\,dx", "2/9*(2sqrt(2)-1)", r"\frac29\left(2\sqrt2-1\right)", "x**2*sqrt(x**3+1)", ("d", "0", "1"), [r"g=x^{3}+1,\ x^{2}=\tfrac13g'", r"\left[\tfrac13\cdot\tfrac23\left(x^{3}+1\right)^{\frac32}\right]_{0}^{1}=\tfrac29\left(2^{\frac32}-1\right)"], "$n=\\tfrac12$: the answer has $(x^{3}+1)^{3/2}$.", "$n=\\tfrac12$ คำตอบมี $(x^{3}+1)^{3/2}$")]),
]
